#define _POSIX_C_SOURCE 200809L
#include "cvc_commands.h"
#include "cvc_object.h"
#include "cvc_worktree.h"
#include "cvc_diff.h"
#include "cvc_glob.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <sys/stat.h>

static int head_snapshot(CvcRepo*r,CvcSnapshot*s){if(!r->born){cvc_snapshot_init(s);return 0;}return cvc_snapshot_from_commit(r->cvc,r->head,s);}
static int filt(const CvcStrVec*in,const CvcStrVec*ex,const char*p){if(!in&&!ex)return 1;CvcStrVec di,de;if(!in){cvc_strvec_init(&di);cvc_strvec_push(&di,"**");in=&di;}else memset(&di,0,sizeof(di));if(!ex){cvc_strvec_init(&de);ex=&de;}else memset(&de,0,sizeof(de));int y=cvc_patterns_select(in,ex,p);if(di.v)cvc_strvec_free(&di);if(de.v)cvc_strvec_free(&de);return y;}
static int change_kind(const CvcSnapEntry*a,const CvcSnapEntry*b){if(!a)return 1;if(!b)return 2;if(a->type!=b->type)return 4;if(memcmp(a->oid,b->oid,32))return 3;return 0;}
static void walk_changes(const CvcSnapshot *a,const CvcSnapshot *b,const CvcStrVec *in,const CvcStrVec *ex,void(*cb)(const CvcSnapEntry*,const CvcSnapEntry*,int,void*),void *ctx){
    size_t i=0,j=0;
    while(i<a->n||j<b->n){
        const CvcSnapEntry *x=NULL,*y=NULL;
        int c;
        if(i==a->n)c=1;
        else if(j==b->n)c=-1;
        else c=strcmp(a->v[i].path,b->v[j].path);
        if(c<0)x=&a->v[i++];
        else if(c>0)y=&b->v[j++];
        else{x=&a->v[i++];y=&b->v[j++];}
        int k=change_kind(x,y);
        const char *path=NULL;
        if(x)path=x->path;
        else if(y)path=y->path;
        if(path&&k&&filt(in,ex,path))cb(x,y,k,ctx);
    }
}
typedef struct { int count; } StatusCtx;
static void status_cb(const CvcSnapEntry*a,const CvcSnapEntry*b,int k,void*ctx){StatusCtx*c=ctx;const char*p=a?a->path:b->path;const char*s=k==1?"added":k==2?"deleted":k==3?"modified":"type-changed";printf("%-12s %s\n",s,p);c->count++;}
int cvc_cmd_status(CvcRepo*r,const CvcStrVec*in,const CvcStrVec*ex){CvcSnapshot h,w;if(head_snapshot(r,&h)<0)return -1;if(cvc_worktree_selected(r,0,&w)<0){cvc_snapshot_free(&h);return -1;}StatusCtx c={0};walk_changes(&h,&w,in,ex,status_cb,&c);if(!c.count)printf("working tree clean\n");printf("ignored: %llu\n",(unsigned long long)w.ignored);cvc_snapshot_free(&h);cvc_snapshot_free(&w);return 0;}
static int read_obj_payload(CvcRepo*r,const CvcSnapEntry*e,CvcBuf*b){CvcObjType t;if(cvc_object_read(r->cvc,e->oid,&t,b)<0)return -1;if((e->type==1&&t!=CVC_OBJ_BLOB)||(e->type==2&&t!=CVC_OBJ_SYMLINK)){cvc_buf_free(b);return cvc_errorf("object type mismatch for %s",e->path);}return 0;}
static uint64_t line_count_bytes(const unsigned char*p,size_t n){if(!n)return 0;uint64_t c=0;for(size_t i=0;i<n;i++)if(p[i]=='\n')c++;if(p[n-1]!='\n')c++;return c;}
static int diff_counts_entries(CvcRepo*r,const CvcSnapEntry*a,const CvcSnapEntry*b,uint64_t*ins,uint64_t*del){*ins=*del=0;if(a&&a->type==1&&b&&b->type==1){CvcBuf x,y;if(read_obj_payload(r,a,&x)<0)return -1;if(read_obj_payload(r,b,&y)<0){cvc_buf_free(&x);return -1;}CvcLines A,B;CvcDiffOps op;cvc_lines_split(x.data,x.len,&A);cvc_lines_split(y.data,y.len,&B);int rc=cvc_myers_diff(&A,&B,&op);if(!rc){cvc_diff_counts(&op,ins,del);cvc_diffops_free(&op);}cvc_lines_free(&A);cvc_lines_free(&B);cvc_buf_free(&x);cvc_buf_free(&y);return rc;}if(a&&a->type==1){CvcBuf x;if(read_obj_payload(r,a,&x)<0)return -1;*del=line_count_bytes(x.data,x.len);cvc_buf_free(&x);}if(b&&b->type==1){CvcBuf y;if(read_obj_payload(r,b,&y)<0)return -1;*ins=line_count_bytes(y.data,y.len);cvc_buf_free(&y);}return 0;}
typedef struct { CvcRepo*r; uint64_t ti,td; int fail; } StatCtx;
static void stat_cb(const CvcSnapEntry*a,const CvcSnapEntry*b,int k,void*vv){(void)k;StatCtx*c=vv;uint64_t i,d;if(diff_counts_entries(c->r,a,b,&i,&d)<0){c->fail=1;return;}const char*p=a?a->path:b->path;if((a&&a->type==1)||(b&&b->type==1)){printf(" %s | +%llu -%llu\n",p,(unsigned long long)i,(unsigned long long)d);c->ti+=i;c->td+=d;}else printf(" %s | changed (symlink/type)\n",p);}
int cvc_cmd_save(CvcRepo*r,const char*msg,const CvcStrVec*cli_in,const CvcStrVec*cli_ex,int no_ds){CvcSnapshot old,nw;if(head_snapshot(r,&old)<0)return -1;int64_t ts;if(cvc_get_timestamp(&ts)<0){cvc_snapshot_free(&old);return -1;}if(cvc_worktree_selected(r,1,&nw)<0){cvc_snapshot_free(&old);return -1;}if(cvc_snapshot_equal(&old,&nw)){printf("nothing to save\n");cvc_snapshot_free(&old);cvc_snapshot_free(&nw);return 0;}uint8_t tree[32];if(cvc_snapshot_write_tree(r->cvc,&nw,tree)<0){cvc_snapshot_free(&old);cvc_snapshot_free(&nw);return -1;}uint8_t parents[2][32]={{0}};uint8_t pc=0;if(r->born){pc=1;memcpy(parents[0],r->head,32);}uint8_t commit[32];if(cvc_commit_store(r->cvc,tree,pc,&parents[0][0],ts,(const unsigned char*)msg,strlen(msg),commit)<0){cvc_snapshot_free(&old);cvc_snapshot_free(&nw);return -1;}if(cvc_branch_write(r,r->branch,1,commit)<0){cvc_snapshot_free(&old);cvc_snapshot_free(&nw);return -1;}r->born=1;memcpy(r->head,commit,32);char h[65];cvc_hex_encode(commit,32,h);printf("saved %s\n",h);int show=r->config.show_diffstat&&!no_ds;if(show){const CvcStrVec*in=cli_in?cli_in:&r->config.diffstat_include;const CvcStrVec*ex=cli_ex?cli_ex:&r->config.diffstat_exclude;StatCtx s={r,0,0,0};walk_changes(&old,&nw,in,ex,stat_cb,&s);if(s.fail){cvc_snapshot_free(&old);cvc_snapshot_free(&nw);return -1;}printf("total: +%llu -%llu\n",(unsigned long long)s.ti,(unsigned long long)s.td);}cvc_snapshot_free(&old);cvc_snapshot_free(&nw);return 0;}
static int load_commit(CvcRepo*r,const uint8_t id[32],CvcCommit*c){CvcObjType t;CvcBuf p;if(cvc_object_read(r->cvc,id,&t,&p)<0)return -1;if(t!=CVC_OBJ_COMMIT){cvc_buf_free(&p);return cvc_errorf("history object is not commit");}int rc=cvc_commit_parse(p.data,p.len,c);cvc_buf_free(&p);if(rc<0)return cvc_errorf("malformed commit in history");return 0;}
int cvc_cmd_log(CvcRepo*r,uint64_t max,int limited){if(!r->born){printf("no commits\n");return 0;}uint8_t id[32];memcpy(id,r->head,32);uint64_t n=0;for(;;){CvcCommit c;if(load_commit(r,id,&c)<0)return -1;char h[65];cvc_hex_encode(id,32,h);printf("commit %s\n",h);if(c.parent_count==0)printf("parents root\n");else{printf("parents");for(unsigned j=0;j<c.parent_count;j++){char p[65];cvc_hex_encode(c.parents[j],32,p);printf(" %s",p);}putchar('\n');}printf("timestamp %lld\nmessage ",(long long)c.timestamp);fwrite(c.message,1,c.message_len,stdout);putchar('\n');n++;if((limited&&n>=max)||c.parent_count==0){cvc_commit_free(&c);break;}memcpy(id,c.parents[0],32);cvc_commit_free(&c);}return 0;}
static int read_work_bytes(CvcRepo*r,const CvcSnapEntry*e,CvcBuf*b){char*p=cvc_path_join(r->root,e->path);if(e->type==1){int rc=cvc_read_file_nofollow(p,b);free(p);return rc<0?cvc_errorf("cannot read working file %s",e->path):0;}cvc_buf_init(b);size_t cap=128;for(;;){b->data=cvc_xrealloc(b->data,cap);ssize_t n=readlink(p,(char*)b->data,cap);if(n<0){free(p);cvc_buf_free(b);return cvc_errorf("cannot read working symlink %s",e->path);}if((size_t)n<cap){b->len=(size_t)n;b->cap=cap;free(p);return 0;}cap*=2;}}
static void print_pref_line(char pre,const CvcLine*l){putchar(pre);fwrite(l->p,1,l->n,stdout);if(!l->n||l->p[l->n-1]!='\n'){putchar('\n');printf("\\ No newline at end of file\n");}}
static int diff_one(CvcRepo*r,const CvcSnapEntry*a,const CvcSnapEntry*b){const char*p=a?a->path:b->path;printf("diff %s\n",p);if(a&&b&&a->type!=b->type)printf("type change %s -> %s\n",a->type==1?"file":"symlink",b->type==1?"file":"symlink");if((a&&a->type==2)||(b&&b->type==2)){if(a&&a->type==2){CvcBuf x;if(read_obj_payload(r,a,&x)<0)return -1;printf("-symlink[%zu] ",x.len);fwrite(x.data,1,x.len,stdout);putchar('\n');cvc_buf_free(&x);}if(b&&b->type==2){CvcBuf y;if(read_work_bytes(r,b,&y)<0)return -1;printf("+symlink[%zu] ",y.len);fwrite(y.data,1,y.len,stdout);putchar('\n');cvc_buf_free(&y);}if(!(a&&a->type==1)||!(b&&b->type==1))return 0;}CvcBuf x,y;cvc_buf_init(&x);cvc_buf_init(&y);if(a&&a->type==1&&read_obj_payload(r,a,&x)<0)return -1;if(b&&b->type==1&&read_work_bytes(r,b,&y)<0){cvc_buf_free(&x);return -1;}CvcLines A,B;CvcDiffOps op;cvc_lines_split(x.data,x.len,&A);cvc_lines_split(y.data,y.len,&B);if(cvc_myers_diff(&A,&B,&op)<0){cvc_lines_free(&A);cvc_lines_free(&B);cvc_buf_free(&x);cvc_buf_free(&y);return -1;}for(size_t i=0;i<op.n;i++){if(op.v[i].op=='-')print_pref_line('-',&A.v[op.v[i].ai]);else if(op.v[i].op=='+')print_pref_line('+',&B.v[op.v[i].bi]);}cvc_diffops_free(&op);cvc_lines_free(&A);cvc_lines_free(&B);cvc_buf_free(&x);cvc_buf_free(&y);return 0;}
typedef struct { CvcRepo*r; int fail; } DiffCtx;
static void diff_cb(const CvcSnapEntry*a,const CvcSnapEntry*b,int k,void*vv){(void)k;DiffCtx*c=vv;if(diff_one(c->r,a,b)<0)c->fail=1;}
int cvc_cmd_diff(CvcRepo*r,const char*rev,const CvcStrVec*in,const CvcStrVec*ex){CvcSnapshot old,w;if(rev){uint8_t id[32];if(cvc_resolve_revision(r,rev,id)<0)return -1;if(cvc_snapshot_from_commit(r->cvc,id,&old)<0)return -1;}else if(head_snapshot(r,&old)<0)return -1;if(cvc_worktree_selected(r,0,&w)<0){cvc_snapshot_free(&old);return -1;}DiffCtx c={r,0};walk_changes(&old,&w,in,ex,diff_cb,&c);if(!c.fail&&cvc_snapshot_equal(&old,&w))printf("no differences\n");cvc_snapshot_free(&old);cvc_snapshot_free(&w);return c.fail?-1:0;}
int cvc_cmd_branch_list(CvcRepo*r){CvcStrVec b;if(cvc_branch_list(r,&b)<0)return -1;for(size_t i=0;i<b.n;i++){int born;uint8_t id[32];if(cvc_branch_read(r,b.v[i],&born,id)<0){cvc_strvec_free(&b);return -1;}printf("%c %s%s\n",strcmp(b.v[i],r->branch)?'-':'*',b.v[i],born?"":" (unborn)");}cvc_strvec_free(&b);return 0;}
int cvc_cmd_branch_create(CvcRepo*r,const char*n){if(cvc_branch_create(r,n)<0)return -1;printf("created branch %s\n",n);return 0;}
int cvc_cmd_branch_delete(CvcRepo*r,const char*n){int warn;if(cvc_branch_delete(r,n,&warn)<0)return -1;if(warn)cvc_warnf("branch %s contains commits unreachable from other branches",n);printf("deleted branch %s\n",n);return 0;}
int cvc_cmd_switch(CvcRepo*r,const char*n){if(!cvc_branch_name_valid(n))return cvc_errorf("invalid branch name");if(!strcmp(n,r->branch)){printf("already on %s\n",n);return 0;}int tb;uint8_t tid[32];if(cvc_branch_read(r,n,&tb,tid)<0)return -1;CvcSnapshot cur,work,target;if(head_snapshot(r,&cur)<0)return -1;int clean;if(cvc_worktree_is_clean(r,&cur,&work,&clean)<0){cvc_snapshot_free(&cur);return -1;}cvc_snapshot_free(&work);if(!clean){cvc_snapshot_free(&cur);return cvc_errorf("working tree has selected changes; switch refused");}if(tb){if(cvc_snapshot_from_commit(r->cvc,tid,&target)<0){cvc_snapshot_free(&cur);return -1;}}else cvc_snapshot_init(&target);if(cvc_materialize_snapshot(r,&cur,&target)<0){cvc_snapshot_free(&cur);cvc_snapshot_free(&target);return -1;}if(cvc_head_write_branch(r,n)<0){cvc_warnf("HEAD update failed; restoring original working tree");if(cvc_materialize_snapshot(r,&target,&cur)<0)cvc_warnf("working-tree rollback after HEAD failure also failed");cvc_snapshot_free(&cur);cvc_snapshot_free(&target);return -1;}free(r->branch);r->branch=cvc_xstrdup(n);r->born=tb;if(tb)memcpy(r->head,tid,32);else memset(r->head,0,32);printf("switched to %s\n",n);cvc_snapshot_free(&cur);cvc_snapshot_free(&target);return 0;}
static int under_operand(const char*p,const char*root){size_t n=strlen(root);return !strcmp(p,root)||(!strncmp(p,root,n)&&p[n]=='/');}
static void snap_clone_except(const CvcSnapshot*s,const char*skip,CvcSnapshot*out){cvc_snapshot_init(out);for(size_t i=0;i<s->n;i++)if(!skip||!under_operand(s->v[i].path,skip))cvc_snapshot_add(out,s->v[i].path,s->v[i].type,s->v[i].oid);}
int cvc_cmd_restore(CvcRepo*r,const char*path,const char*rev){uint8_t id[32];if(cvc_resolve_revision(r,rev,id)<0)return -1;CvcSnapshot src,head,desired;if(cvc_snapshot_from_commit(r->cvc,id,&src)<0)return -1;if(head_snapshot(r,&head)<0){cvc_snapshot_free(&src);return -1;}int found=0;for(size_t i=0;i<src.n;i++)if(under_operand(src.v[i].path,path)){found=1;break;}if(!found){cvc_snapshot_free(&src);cvc_snapshot_free(&head);return cvc_errorf("path absent from source revision");}snap_clone_except(&head,path,&desired);for(size_t i=0;i<src.n;i++)if(under_operand(src.v[i].path,path))cvc_snapshot_add(&desired,src.v[i].path,src.v[i].type,src.v[i].oid);cvc_snapshot_sort(&desired);CvcStrVec owned;cvc_strvec_init(&owned);cvc_strvec_push(&owned,path);int rc=cvc_materialize_snapshot_owned(r,&head,&desired,&owned);cvc_strvec_free(&owned);if(rc==0)printf("restored %s\n",path);cvc_snapshot_free(&src);cvc_snapshot_free(&head);cvc_snapshot_free(&desired);return rc;}
int cvc_cmd_rollback(CvcRepo*r,const char*rev,const char*msg){if(!r->born)return cvc_errorf("cannot rollback unborn branch");uint8_t tid[32];if(cvc_resolve_revision(r,rev,tid)<0)return -1;CvcSnapshot cur,work,target;if(head_snapshot(r,&cur)<0)return -1;int clean;if(cvc_worktree_is_clean(r,&cur,&work,&clean)<0){cvc_snapshot_free(&cur);return -1;}cvc_snapshot_free(&work);if(!clean){cvc_snapshot_free(&cur);return cvc_errorf("working tree has selected changes; rollback refused");}if(cvc_snapshot_from_commit(r->cvc,tid,&target)<0){cvc_snapshot_free(&cur);return -1;}CvcObjType tt;CvcBuf cp;if(cvc_object_read(r->cvc,tid,&tt,&cp)<0){cvc_snapshot_free(&cur);cvc_snapshot_free(&target);return -1;}CvcCommit tc;if(tt!=CVC_OBJ_COMMIT||cvc_commit_parse(cp.data,cp.len,&tc)<0){cvc_buf_free(&cp);cvc_snapshot_free(&cur);cvc_snapshot_free(&target);return cvc_errorf("target is not valid commit");}cvc_buf_free(&cp);int64_t ts;if(cvc_get_timestamp(&ts)<0){cvc_commit_free(&tc);cvc_snapshot_free(&cur);cvc_snapshot_free(&target);return -1;}uint8_t parents[2][32]={{0}};memcpy(parents[0],r->head,32);uint8_t nid[32];if(cvc_commit_store(r->cvc,tc.root,1,&parents[0][0],ts,(const unsigned char*)msg,strlen(msg),nid)<0){cvc_commit_free(&tc);cvc_snapshot_free(&cur);cvc_snapshot_free(&target);return -1;}cvc_commit_free(&tc);if(cvc_materialize_snapshot(r,&cur,&target)<0){cvc_snapshot_free(&cur);cvc_snapshot_free(&target);return -1;}if(cvc_branch_write(r,r->branch,1,nid)<0){cvc_warnf("rollback ref update failed; restoring original working tree");if(cvc_materialize_snapshot(r,&target,&cur)<0)cvc_warnf("rollback restoration failed");cvc_snapshot_free(&cur);cvc_snapshot_free(&target);return -1;}memcpy(r->head,nid,32);char h[65];cvc_hex_encode(nid,32,h);printf("rollback commit %s\n",h);cvc_snapshot_free(&cur);cvc_snapshot_free(&target);return 0;}
